// ICU79.1-only native smoke fixture producer. No production data is exported.
#define SOUNIO_CLDR_GRAPH_ORACLE_NO_MAIN
#include "cldr_graph_oracle.cpp"
void source_text(std::ostream&out,const std::string&name,const Fseq&text){
 std::vector<unsigned> bytes;for(auto cp:text){if(cp<=0x7f)bytes.push_back(cp);else if(cp<=0x7ff){bytes.push_back(0xc0+(cp>>6));bytes.push_back(0x80+(cp&63));}else if(cp<=0xffff){bytes.push_back(0xe0+(cp>>12));bytes.push_back(0x80+((cp>>6)&63));bytes.push_back(0x80+(cp&63));}else{bytes.push_back(0xf0+(cp>>18));bytes.push_back(0x80+((cp>>12)&63));bytes.push_back(0x80+((cp>>6)&63));bytes.push_back(0x80+(cp&63));}}
 out<<"fn "<<name<<"()->Utf8Text with Alloc,Mut,Div,Panic {\n var b=byte_buffer_new(4096)\n";for(auto byte:bytes)out<<" assert(byte_buffer_push(&!b,"<<byte<<")==0)\n";out<<" let text=utf8_text_from_bytes(&b,4096)\n byte_buffer_close(b)\n text\n}\n";
}
struct NativePair{std::string locale,type;Fseq left,right;};
int main(int argc,char**argv){try{if(argc!=4)return 64;g_oracle_versions();cldr_input_versions(argv[1],argv[2]);Registry registry(argv[1]);std::vector<NativePair> pairs={
 {"de","phonebook",{0xe4},{0x61,0x65}},{"sv","standard",{0x7a},{0xe4}},{"es","traditional",{0x63,0x68},{0x64}},{"cs","standard",{0x68},{0x63,0x68}},
 {"tr","standard",{0x69},{0x49}},{"lt","standard",{0x69,0x301},{0x69,0x307,0x301}},{"ja","standard",{0x3042},{0x30a2}},{"zh","pinyin",{0x963f},{0x516b}},
 {"zh","stroke",{0x4e00},{0x4e01}},{"zh","unihan",{0x4e00},{0x4e01}},{"ko","searchjl",{0xac00},{0x1100,0x1161}},{"root","emoji",{0x1f600},{0x2764}},
 {"root","search",{0xf6},{0x6f}},{"da","standard",{0x61,0x61},{0xe5}},{"fr","standard",{0x61,0x301,0x62,0x300},{0x61,0x300,0x62,0x301}},
 {"root","standard",{0x61,0x301,0xfffe,0x62,0x300},{0x61,0x300,0xfffe,0x62,0x301}},{"root","standard",{0},{}},
 {"cu","standard",{0xa64d},{0x47c}},{"aa","standard",{0xe9},{0x6b}},{"root","standard",{0xfdd1,0xac00},{0x1100}},
 {"root","standard",{0x378},{0xfdd0,0x34}},{"ja","standard",{0x3042,0x30fc},{0x3042,0x3042}}
 };
 std::ofstream out(argv[3]);out<<"//@ run-pass\n//@ expect-stdout: CLDR_NATIVE_KEY_SMOKE_OK\n";
 out<<"use text::utf8::{Utf8Text,utf8_text_from_string,utf8_text_from_bytes,utf8_text_close}\nuse collections::byte_buffer::{byte_buffer_new,byte_buffer_push,byte_buffer_close}\nuse text::locale_collation::{UnicodeLocaleOptions,unicode_locale_collator,unicode_locale_collator_status,unicode_locale_collation_key,unicode_locale_key_status,unicode_locale_key_compare,unicode_locale_key_close}\n";
 out<<"fn test(name:string,kind:string,left:&Utf8Text,right:&Utf8Text,strength:i64,alternate:i64,backwards:i64,case_level:i64,case_first:i64,max_variable:i64,want:i64) with Alloc,Mut,Div,Panic {\n let locale=utf8_text_from_string(name,512)\n let ty=utf8_text_from_string(kind,512)\n let options=UnicodeLocaleOptions {strength:strength,alternate:alternate,backwards_secondary:backwards,case_level:case_level,case_first:case_first,max_variable:max_variable}\n let c=unicode_locale_collator(&locale,&ty,&options,8192)\n assert(unicode_locale_collator_status(&c)==0)\n let a=unicode_locale_collation_key(&c,left,65536,262144)\n let b=unicode_locale_collation_key(&c,right,65536,262144)\n assert(unicode_locale_key_status(&a)==0)\n assert(unicode_locale_key_status(&b)==0)\n let order=unicode_locale_key_compare(&a,&b)\n assert(order.status==0)\n assert(order.order==want)\n unicode_locale_key_close(a);unicode_locale_key_close(b);utf8_text_close(locale);utf8_text_close(ty)\n}\n";
 std::uint64_t cases=0;for(std::size_t i=0;i<pairs.size();++i){source_text(out,"left_"+std::to_string(i),pairs[i].left);source_text(out,"right_"+std::to_string(i),pairs[i].right);out<<"fn pair_"<<i<<"() with Alloc,Mut,Div,Panic {\n let a=left_"<<i<<"()\n let b=right_"<<i<<"()\n";const auto&t=registry.entries.at(registry.resolve(pairs[i].locale,pairs[i].type));auto c=g_compile(t);for(unsigned strength=1;strength<=5;++strength)for(unsigned pattern=0;pattern<4;++pattern){unsigned alternate=pattern&1,backwards=(pattern>>1)&1,case_level=pattern==2?1U:0U,case_first=pattern==1?2U:pattern==2?1U:0U,max_variable=pattern;UErrorCode e=U_ZERO_ERROR;ucol_setAttribute(c,UCOL_STRENGTH,strength==5?UCOL_IDENTICAL:static_cast<UColAttributeValue>(strength-1),&e);ucol_setAttribute(c,UCOL_ALTERNATE_HANDLING,alternate?UCOL_SHIFTED:UCOL_NON_IGNORABLE,&e);ucol_setAttribute(c,UCOL_FRENCH_COLLATION,backwards?UCOL_ON:UCOL_OFF,&e);ucol_setAttribute(c,UCOL_CASE_LEVEL,case_level?UCOL_ON:UCOL_OFF,&e);ucol_setAttribute(c,UCOL_CASE_FIRST,case_first==2?UCOL_UPPER_FIRST:case_first==1?UCOL_LOWER_FIRST:UCOL_OFF,&e);ucol_setAttribute(c,UCOL_NORMALIZATION_MODE,UCOL_ON,&e);const std::array<UColReorderCode,4> vars{UCOL_REORDER_CODE_SPACE,UCOL_REORDER_CODE_PUNCTUATION,UCOL_REORDER_CODE_SYMBOL,UCOL_REORDER_CODE_CURRENCY};ucol_setMaxVariable(c,vars[max_variable],&e);if(U_FAILURE(e))bad("fixture ICU attributes");auto a=g_utf16(pairs[i].left),b=g_utf16(pairs[i].right);auto result=ucol_strcoll(c,a.empty()?u"":a.data(),static_cast<int32_t>(a.size()),b.empty()?u"":b.data(),static_cast<int32_t>(b.size()));int want=result<0?-1:result>0?1:0;out<<" test(\""<<pairs[i].locale<<"\",\""<<pairs[i].type<<"\",&a,&b,"<<strength<<','<<alternate<<','<<backwards<<','<<case_level<<','<<case_first<<','<<max_variable<<','<<(want<0?"0-1":std::to_string(want))<<")\n";++cases;}ucol_close(c);out<<" utf8_text_close(a);utf8_text_close(b)\n}\n";}
 out<<"fn main() with IO,Alloc,Mut,Div,Panic {\n";for(std::size_t i=0;i<pairs.size();++i)out<<" pair_"<<i<<"()\n";out<<" println(\"CLDR_NATIVE_KEY_SMOKE_OK\")\n}\n";if(!out)bad("native fixture output");std::cout<<"CLDR_NATIVE_FIXTURE_OK pairs="<<pairs.size()<<" cases="<<cases<<"\n";return 0;
}catch(const std::exception&e){std::cerr<<"CLDR_NATIVE_FIXTURE_ERROR "<<e.what()<<"\n";return 1;}}
